#include <zephyr/kernel.h>

#include <zephyr/ztest.h> 

#include <zephyr/usb/usb_device.h>
#include <zephyr/usb/usbd.h>
#include <zephyr/usb/class/usbd_uac2.h>
#include <zephyr/usb/class/audio.h>

#define OT_ID 4
#define FU_ID 3
#define IT_ID 2
#define CLK_ID 1

#define AS_IFACE_NUM 1
#define AC_IFACE_NUM 0

#define STR_DESC_IDX_IF_AC 4

static struct usbd_string_descriptor sample_lang = {
	bLength = sizeof(struct usbd_string_descriptor),
	bDescriptorType = USB_DESC_STRING,
	wLANGID = {
		sys_cpu_to_le16(0x0409),
	},
};

static struct usbd_string_descriptor sample_mfr = {
	bLength = 0,
	bDescriptorType = USB_DESC_STRING,
	bString = "ZEPHYR",
};

static struct usbd_string_descriptor sample_product = {
	bLength = 0,
	bDescriptorType = USB_DESC_STRING,
	bString = "Zephyr UAC2 sample",
};

static struct usbd_string_descriptor sample_sn = {
	bLength = 0,
	bDescriptorType = USB_DESC_STRING,
	bString = "0123456789ABCDEF",
};

static struct usbd_string_descriptor sample_iface_ac_desc = {
	bLength = 0,
	bDescriptorType = USB_DESC_STRING,
	bString = "AudioControl Interface",
};

static struct usbd_string_descriptor *string_descs[] = {
	&sample_lang,
	&sample_mfr,
	&sample_product,
	&sample_sn,
	&sample_iface_ac_desc,
};

USBD_DEVICE_INFO_DEFINE(uac2, DEVICE_DT_GET(DT_NODELABEL(zephyr_udc0)),
	.vid = 0x1234, .pid = 0x5678);

/* FS and HS are using the same items */
#define UAC2_FS_HS_CONFIG

UAC2_AC_HEADER_DESCRIPTOR_DEFINE(ac_iface, AS_IFACE_NUM);

UAC2_ENTITY_CLOCK_SOURCE_DESCRIPTOR_DEFINE(clk_src, CLK_ID, 0, 0);

UAC2_ENTITY_INPUT_TERMINAL_DESCRIPTOR_DEFINE(it, IT_ID, USB_TERMINAL_USB_STREAMING, 0, 2, 0);

UAC2_ENTITY_OUTPUT_TERMINAL_DESCRIPTOR_DEFINE(ot, OT_ID, USB_TERMINAL_SPEAKER, 0, CLK_ID, 0);

static const uint8_t ch_config[] = {UAC2_FU_CHANNEL_CONFIG(UAC2_FU_MUTE_CONTROL)};
UAC2_ENTITY_FEATURE_UNIT_DESCRIPTOR_DEFINE(fu, FU_ID, IT_ID, 1, ch_config);

UAC2_AC_INTERFACE_DESCRIPTOR_DEFINE(ac_iface, AC_IFACE_NUM, STR_DESC_IDX_IF_AC,
	&ac_iface_header_desc, &clk_src_desc, &it_desc, &fu_desc, &ot_desc);

UAC2_AS_INTERFACE_DESCRIPTOR_DEFINE(as_iface_alt_0, AS_IFACE_NUM, 0, 0);

UAC2_AS_INTERFACE_DESCRIPTOR_DEFINE(as_iface_alt_1, AS_IFACE_NUM, 1, 1);

UAC2_AS_HEADER_DESCRIPTOR_DEFINE(as_iface, IT_ID, 2, UAC_FORMAT_TYPE_I_PCM);

UAC2_FORMAT_TYPE_I_DESCRIPTOR_DEFINE(format_type, 2, 2);

static struct usbd_uac2_iso_ep_desc fs_iso_ep_out_desc = {
	.ep_addr = 0x01,
	.ep_attr = USB_EP_TYPE_ISO | USB_EP_SYNC_ASYNC,
	.ep_mps = 192,
	.ep_interval = 1,
};

static struct usbd_uac2_iso_ep_desc hs_iso_ep_out_desc = {
	.ep_addr = 0x01,
	.ep_attr = USB_EP_TYPE_ISO | USB_EP_SYNC_ASYNC,
	.ep_mps = 192,
	.ep_interval = 4,
};

static struct usbd_class_data_uac2 uac2_data;

static struct usbd_class_node class_uac2 = {
	.data = (struct usbd_class_data *)&uac2_data,
	.ops = &uac2_ops,
};

static struct usbd_interface_config_uac2 ac_iface_cfg = {
	.iface_desc = &ac_iface_desc,
};

static struct usbd_interface_config_uac2 as_iface_alt_0_cfg = {
	.iface_desc = &as_iface_alt_0_desc,
};

static struct usbd_interface_config_uac2 as_iface_alt_1_cfg = {
	.iface_desc = &as_iface_alt_1_desc,
	.payload = &as_iface_header_desc,
	.fs_ep = &fs_iso_ep_out_desc,
	.hs_ep = &hs_iso_ep_out_desc,
};

static struct usbd_interface_list uac2_iface_list[] = {
	{
		.num_configs = 1,
		.configs = &ac_iface_cfg,
	},
	{
		.num_configs = 2,
		.configs = (struct usbd_interface_config *)&(struct usbd_interface_config_uac2 *[]){
			&as_iface_alt_0_cfg,
			&as_iface_alt_1_cfg,
		}[0],
	},
};

USBD_CONFIGURATION_DEFINE(fs_config, USB_SCD_SELF_POWERED, 200);

static const uint8_t *const fs_config_data;

/* Reference descriptors */
static const struct usb_if_descriptor reference_ac_interface_descriptor = {
	.bLength = sizeof(struct usb_if_descriptor),
	.bDescriptorType = USB_DESC_INTERFACE,
	.bInterfaceNumber = AC_IFACE_NUM,
	.bAlternateSetting = 0,
	.bNumEndpoints = 0,
	.bInterfaceClass = USB_BCLASS_AUDIO,
	.bInterfaceSubClass = USB_BSUBCLASS_AUDIOCONTROL,
	.bInterfaceProtocol = UAC_V2,
	.iInterface = STR_DESC_IDX_IF_AC,
};

static const struct uac2_ac_header_descriptor reference_ac_header_descriptor = {
	.bLength = sizeof(struct uac2_ac_header_descriptor) + 1,
	.bDescriptorType = USB_DESC_CS_INTERFACE,
	.bDescriptorSubtype = UAC_AC_HEADER,
	.bcdADC = sys_cpu_to_le16(0x0200),
	.bCategory = 0x00,
	.wTotalLength = sys_cpu_to_le16(sizeof(struct uac2_ac_header_descriptor) + 1 +
		sizeof(struct uac2_clock_source_descriptor) +
		sizeof(struct uac2_input_terminal_descriptor) +
		sizeof(struct uac2_feature_unit_descriptor) + 1 +
		sizeof(struct uac2_output_terminal_descriptor)),
	.bmControls = 0x00,
	.bInCollection = 1,
	.baInterfaceNr = {AS_IFACE_NUM},
};

static const struct uac2_clock_source_descriptor reference_clk_src_descriptor = {
	.bLength = sizeof(struct uac2_clock_source_descriptor),
	.bDescriptorType = USB_DESC_CS_INTERFACE,
	.bDescriptorSubtype = UAC_AC_CLOCK_SOURCE,
	.bClockID = CLK_ID,
	.bmAttributes = 0x01,
	.bmControls = 0x07,
	.bAssocTerminal = 0x00,
	.iClockSource = 0,
};

static const struct uac2_input_terminal_descriptor reference_it_descriptor = {
	.bLength = sizeof(struct uac2_input_terminal_descriptor),
	.bDescriptorType = USB_DESC_CS_INTERFACE,
	.bDescriptorSubtype = UAC_AC_INPUT_TERMINAL,
	.bTerminalID = IT_ID,
	.wTerminalType = sys_cpu_to_le16(USB_TERMINAL_USB_STREAMING),
	.bAssocTerminal = 0x00,
	.bCSourceID = CLK_ID,
	.bNrChannels = 2,
	.bmChannelConfig = sys_cpu_to_le32(0x00000003),
	.iChannelNames = 0,
	.bmControls = sys_cpu_to_le16(0x0000),
	.iTerminal = 0,
};

static const struct uac2_feature_unit_descriptor reference_fu_descriptor = {
	.bLength = sizeof(struct uac2_feature_unit_descriptor) + 1,
	.bDescriptorType = USB_DESC_CS_INTERFACE,
	.bDescriptorSubtype = UAC_AC_FEATURE_UNIT,
	.bUnitID = FU_ID,
	.bSourceID = IT_ID,
	.bmaControls[0] = 0x03,
	.iFeature = 0,
};

static const struct uac2_output_terminal_descriptor reference_ot_descriptor = {
	.bLength = sizeof(struct uac2_output_terminal_descriptor),
	.bDescriptorType = USB_DESC_CS_INTERFACE,
	.bDescriptorSubtype = UAC_AC_OUTPUT_TERMINAL,
	.bTerminalID = OT_ID,
	.wTerminalType = sys_cpu_to_le16(USB_TERMINAL_SPEAKER),
	.bAssocTerminal = 0x00,
	.bSourceID = FU_ID,
	.bCSourceID = CLK_ID,
	.bmControls = sys_cpu_to_le16(0x0000),
	.iTerminal = 0,
};

static void test_uac2_descriptors(const uint8_t *const config_data,
				  const size_t size)
{
	const uint8_t *ptr = config_data;
	const struct usb_cfg_descriptor *cfg_desc;
	const struct usb_if_descriptor *if_desc;

	cfg_desc = (const struct usb_cfg_descriptor *)ptr;
	zassert_equal(cfg_desc->bLength, sizeof(struct usb_cfg_descriptor));
	zassert_equal(cfg_desc->bDescriptorType, USB_DESC_CONFIGURATION);
	zassert_equal(sys_le16_to_cpu(cfg_desc->wTotalLength), size);
	ptr += cfg_desc->bLength;

	/* AudioControl Interface */
	if_desc = (const struct usb_if_descriptor *)ptr;
	zassert_mem_equal(if_desc, &reference_ac_interface_descriptor,
			  sizeof(struct usb_if_descriptor),
			  "reference_ac_interface_descriptor not equal to *ptr");
	ptr += if_desc->bLength;

	const struct uac2_ac_header_descriptor *ac_header_desc;

	ac_header_desc = (const struct uac2_ac_header_descriptor *)ptr;
	zassert_mem_equal(ac_header_desc, &reference_ac_header_descriptor,
			  sizeof(struct uac2_ac_header_descriptor) + 1,
			  "reference_ac_header_descriptor not equal to *ptr");
	ptr += ac_header_desc->bLength;

	const struct uac2_clock_source_descriptor *clk_src_desc_ptr;

	clk_src_desc_ptr = (const struct uac2_clock_source_descriptor *)ptr;
	zassert_mem_equal(clk_src_desc_ptr, &reference_clk_src_descriptor,
			  sizeof(struct uac2_clock_source_descriptor),
			  "reference_clk_src_descriptor not equal to *ptr");
	ptr += clk_src_desc_ptr->bLength;

	const struct uac2_input_terminal_descriptor *it_desc_ptr;

	it_desc_ptr = (const struct uac2_input_terminal_descriptor *)ptr;
	zassert_mem_equal(it_desc_ptr, &reference_it_descriptor,
			  sizeof(struct uac2_input_terminal_descriptor),
			  "reference_it_descriptor not equal to *ptr");
	ptr += it_desc_ptr->bLength;

	const struct uac2_feature_unit_descriptor *fu_desc_ptr;

	fu_desc_ptr = (const struct uac2_feature_unit_descriptor *)ptr;
	zassert_mem_equal(fu_desc_ptr, &reference_fu_descriptor,
			  sizeof(struct uac2_feature_unit_descriptor) + 1,
			  "reference_fu_descriptor not equal to *ptr");
	ptr += fu_desc_ptr->bLength;

	const struct uac2_output_terminal_descriptor *ot_desc_ptr;

	ot_desc_ptr = (const struct uac2_output_terminal_descriptor *)ptr;
	zassert_mem_equal(ot_desc_ptr, &reference_ot_descriptor,
			  sizeof(struct uac2_output_terminal_descriptor),
			  "reference_ot_descriptor not equal to *ptr");
	ptr += ot_desc_ptr->bLength;
}

ZTEST(uac2_desc, test_fs_uac2_descriptors)
{
	test_uac2_descriptors(fs_config_data, fs_config.wTotalLength);
}

ZTEST(uac2_desc, test_fs_hs_iface_and_ep_descriptors_not_shared)
{
	zassert_not_equal(as_iface_alt_1_cfg.fs_ep, as_iface_alt_1_cfg.hs_ep,
			"FS and HS endpoint descriptors should not be shared");
}

static void *uac2_desc_setup(void)
{
	int err;

	usbd_add_class(&uac2_info, &class_uac2, 1);
	usbd_add_interface(&uac2_info, &class_uac2, &uac2_iface_list[0]);
	usbd_add_interface(&uac2_info, &class_uac2, &uac2_iface_list[1]);

	for (int i = 0; i < ARRAY_SIZE(string_descs); i++) {
		usbd_add_string_descriptor(&uac2_info, string_descs[i]);
	}

	usbd_add_configuration(&uac2_info, &fs_config);

	err = usbd_init(&uac2_info);
	zassert_ok(err, "usbd_init failed");

	*(const uint8_t **)&fs_config_data = usbd_get_descriptor(&uac2_info, 0, 0x02, 0);

	return NULL;
}

ZTEST_SUITE(uac2_desc, NULL, uac2_desc_setup, NULL, NULL, NULL);
